namespace sv_5ff5a7930e1c4d5aa6dd50d2460906d3.Client.Models;

public sealed class Shipment
{
    public required string TrackingNumber { get; init; }
    public required string Status { get; init; }
    public required string Location { get; init; }
    public DateTimeOffset? EstimatedDelivery { get; init; }
    public required IReadOnlyList<StatusUpdate> Updates { get; init; }
}

public sealed class StatusUpdate
{
    public required DateTimeOffset Timestamp { get; init; }
    public required string Description { get; init; }
    public required string Location { get; init; }
}

using sv_5ff5a7930e1c4d5aa6dd50d2460906d3.Client.Models;

namespace sv_5ff5a7930e1c4d5aa6dd50d2460906d3.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;
using sv_5ff5a7930e1c4d5aa6dd50d2460906d3.Client.Models;

namespace sv_5ff5a7930e1c4d5aa6dd50d2460906d3.Client.Services;

/// <summary>
/// WASM-side implementation that calls the server API.
/// </summary>
public sealed class HttpShipmentService(HttpClient http) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

using sv_5ff5a7930e1c4d5aa6dd50d2460906d3.Client.Models;
using sv_5ff5a7930e1c4d5aa6dd50d2460906d3.Client.Services;

namespace sv_5ff5a7930e1c4d5aa6dd50d2460906d3.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-1001"] = new Shipment
        {
            TrackingNumber = "TRK-1001",
            Status = "In Transit",
            Location = "Memphis, TN",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 7, 17, 0, 0, TimeSpan.Zero),
            Updates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 1, 8, 0, 0, TimeSpan.Zero), Description = "Package picked up", Location = "Los Angeles, CA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 2, 14, 30, 0, TimeSpan.Zero), Description = "Arrived at sorting facility", Location = "Phoenix, AZ" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 3, 22, 15, 0, TimeSpan.Zero), Description = "Departed facility", Location = "Memphis, TN" },
            ]
        },
        ["TRK-2002"] = new Shipment
        {
            TrackingNumber = "TRK-2002",
            Status = "Delivered",
            Location = "Seattle, WA",
            EstimatedDelivery = null,
            Updates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 5, 28, 9, 0, 0, TimeSpan.Zero), Description = "Package picked up", Location = "Portland, OR" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 5, 29, 11, 0, 0, TimeSpan.Zero), Description = "In transit", Location = "Tacoma, WA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 5, 30, 10, 45, 0, TimeSpan.Zero), Description = "Out for delivery", Location = "Seattle, WA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 5, 30, 14, 20, 0, TimeSpan.Zero), Description = "Delivered — left at front door", Location = "Seattle, WA" },
            ]
        },
        ["TRK-3003"] = new Shipment
        {
            TrackingNumber = "TRK-3003",
            Status = "Label Created",
            Location = "New York, NY",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 12, 20, 0, 0, TimeSpan.Zero),
            Updates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 3, 16, 0, 0, TimeSpan.Zero), Description = "Shipping label created", Location = "New York, NY" },
            ]
